# -*- coding: utf-8 -*-
from common import md, esc, cq, wq
from p_hist import tbl
def venn():
    return '''<figure class="glass reveal svgwrap"><svg class="syn" viewBox="0 0 800 430" role="img" aria-label="四福音独有材料比例">
<circle cx="300" cy="190" r="140" fill="#f5b942" fill-opacity=".28" stroke="#f5b942" stroke-width="3"/>
<circle cx="420" cy="190" r="140" fill="#ff6b8b" fill-opacity=".28" stroke="#ff6b8b" stroke-width="3"/>
<circle cx="360" cy="285" r="140" fill="#4cd3c2" fill-opacity=".28" stroke="#4cd3c2" stroke-width="3"/>
<circle cx="680" cy="210" r="95" fill="#8f8bff" fill-opacity=".30" stroke="#8f8bff" stroke-width="3"/>
<text x="230" y="140" class="vt">马太</text><text x="460" y="140" class="vt">马可</text><text x="360" y="362" class="vt" text-anchor="middle">路加</text><text x="680" y="190" class="vt" text-anchor="middle">约翰</text>
<text x="230" y="168" class="vs2">独有 ≈42%</text><text x="465" y="168" class="vs2">独有 ≈7%</text><text x="360" y="390" class="vs2" text-anchor="middle">独有 ≈59%</text><text x="680" y="218" class="vs2" text-anchor="middle">独有 ≈92%</text>
<text x="360" y="225" class="vs2" text-anchor="middle">三卷共有</text><text x="360" y="245" class="vs2" text-anchor="middle">“三重传统”</text>
<text x="680" y="250" class="vs2" text-anchor="middle">对观福音之外</text>
</svg><figcaption>近似比例（Westcott 1860 年代的经典统计，常被引用；不同统计方法数字略有出入）：马可约 93% 的内容也见于马太或路加，而约翰约 92% 的内容是独有的。</figcaption></figure>'''
PW=[("星期日","🌿","骑驴进耶路撒冷；群众高呼“和散那”","太21:1-11；可11:1-11；路19:28-44；约12:12-19"),
    ("星期一","🌳","咒诅无花果树；洁净圣殿","太21:12-19；可11:12-19"),
    ("星期二","🗣️","无花果树枯干；圣殿中的辩论（权柄、纳税、复活、最大的诫命）；对法利赛人的“七祸”；橄榄山讲论","太21:20–25:46；可11:20–13:37"),
    ("星期三","🤫","（经文较少记载）犹大与祭司长约定出卖耶稣","太26:14-16；可14:10-11"),
    ("星期四","🍞","预备逾越节；洗脚；最后晚餐设立圣餐；楼上讲论；大祭司的祷告；客西马尼；被捕","太26:17-56；约13–18:11"),
    ("星期五","✝️","夜审（亚那、该亚法、公会）；彼得不认主；彼拉多、希律前受审；钉十字架（约上午九时到下午三时）；十架七言；埋葬","太26:57–27:61；约18:12–19:42"),
    ("星期六","🪨","安息日：耶稣的身体在坟墓中；祭司长封石、派兵看守","太27:62-66；路23:56"),
    ("星期日","🌅","妇女发现空坟；复活的主显现","太28；可16；路24；约20")]
WORDS=[("父啊，赦免他们，因为他们所做的，他们不晓得。","路23:34","赦免"),("我实在告诉你，今日你要同我在乐园里了。","路23:43","救恩"),("母亲，看你的儿子！……看你的母亲！","约19:26-27","关怀"),
       ("以罗伊，以罗伊！拉马撒巴各大尼？……我的神，我的神，为什么离弃我？","可15:34","被弃"),("我渴了。","约19:28","受苦"),("成了！","约19:30","完成"),("父啊，我将我的灵魂交在你手里。","路23:46","交托")]
APPEAR=[("抹大拉的马利亚","坟墓旁","约20:11-18"),("其他妇女","往城里的路上","太28:9-10"),("彼得（矶法）","耶路撒冷","路24:34；林前15:5"),("两个门徒","以马忤斯路上","路24:13-35"),("十个门徒（多马不在）","耶路撒冷楼房","路24:36-43；约20:19-23"),
        ("十一个门徒（多马在）","耶路撒冷","约20:26-29"),("七个门徒","提比哩亚海边","约21:1-23"),("十一个门徒","加利利的山上（大使命）","太28:16-20"),("五百多弟兄","（可能在加利利）","林前15:6"),("雅各","—","林前15:7"),("众使徒","伯大尼附近（升天）","路24:50-51；徒1:3-11")]
def build():
    b=[]
    b.append('<h2 id="s1">一、对观问题：为什么前三卷这么相似？</h2>')
    b.append('<div class="card glass"><p>'+md("马太、马可、路加常有**相同的次序、相同的字句**，可以并排“一同观看”（syn-optic），所以称为**对观福音**；约翰则大多不同。这引出**对观问题**：三卷之间是什么关系？")+'</p></div>')
    b.append(tbl(["理论","内容","评估"],[["马可优先说 + Q 源","马可最早；马太与路加各自使用马可及一个假设的语录集“Q”","当今学界主流；“Q”没有任何抄本证据"],["马可优先说（无 Q）","马可最早；路加也使用了马太（Farrer 假说）","可以省去假设的 Q"],["奥古斯丁说","按正典次序：马太 → 马可 → 路加","早期教会传统（马太最早）"],["格里斯巴赫说","马太 → 路加 → 马可（马可综合两者）","少数学者支持"],["独立见证说","三卷主要依靠各自的使徒见证与口传","强调见证人，但难以解释大量逐字相同"]]))
    b.append('<div class="callout key-c"><b>📖 改革宗立场：</b>'+md("不论作者使用了什么资料，**圣灵的默示**保证最终成书的每一句都是神的话。路加自己就说他“从起头都详细考察了”（{{路1:3}}）——**使用资料与圣灵默示并不冲突**。改革宗拒绝那种把福音书拆成“教会创作”的批判方法，因为它否认经文是可靠的见证（{{约21:24}}）。")+'</div>'+cq(("bc",3,"我们承认神的话语不是出于人意，而是如使徒彼得所说的，人被圣灵感动说出神的话来（彼后1:21）。")))
    b.append('<h3 id="s1b">🔵 独有材料比例</h3>'+venn())
    b.append('<h3 id="s1c">🧩 差异不是矛盾</h3><div class="why3">'+"".join(f'<div class="w3 glass reveal"><span>{a}</span><b>{c}</b><p>{md(d)}</p></div>' for a,c,d in [
      ("🎥","不同的镜头","四位见证人从不同角度报道同一事件：一个天使（马可）或两个天使（路加）——提到两个的，并没有否认一个。"),
      ("🗂️","按主题而非时序","古代传记常按主题编排（马太把神迹集中在 8–9 章）；“按着次序”（{{路1:3}}）不一定指严格时序。"),
      ("🗣️","重述而非录音","福音书传达耶稣话语的**真实意思**（ipsissima vox），不一定是逐字录音；耶稣多用亚兰语讲话，福音书用希腊文记录。"),
      ("🔁","多次教导","巡回教师会在不同场合重复相似的教训：马太的登山宝训与路加的平原宝训（{{路6:17}}）可能是不同场合。")])+'</div>')
    b.append('<h2 id="s2">二、福音和谐：一张平行对照表</h2><p class="note">“和谐”指把四卷对照排列，看出一个连贯的故事。二世纪的塔提安曾把四卷编成一本《四福音合参》（Diatessaron），但教会最终保留四卷独立的见证。</p>')
    b.append(tbl(["事件","马太","马可","路加","约翰"],[
      ["序言 / 家谱","{{太1:1-17}}","—","{{路3:23-38}}","{{约1:1-18}}"],["耶稣降生","{{太1:18-25}}","—","{{路2:1-20}}","—"],["约翰施洗","{{太3:1-12}}","{{可1:1-8}}","{{路3:1-20}}","{{约1:19-28}}"],
      ["耶稣受洗","{{太3:13-17}}","{{可1:9-11}}","{{路3:21-22}}","{{约1:32-34}}"],["旷野试探","{{太4:1-11}}","{{可1:12-13}}","{{路4:1-13}}","—"],["变水为酒","—","—","—","{{约2:1-11}}"],
      ["拣选十二使徒","{{太10:1-4}}","{{可3:13-19}}","{{路6:12-16}}","—"],["平静风浪","{{太8:23-27}}","{{可4:35-41}}","{{路8:22-25}}","—"],["五饼二鱼","{{太14:13-21}}","{{可6:30-44}}","{{路9:10-17}}","{{约6:1-14}}"],
      ["彼得认信","{{太16:13-20}}","{{可8:27-30}}","{{路9:18-21}}","（参{{约6:68-69}}）"],["登山变像","{{太17:1-8}}","{{可9:2-8}}","{{路9:28-36}}","—"],["拉撒路复活","—","—","—","{{约11:1-44}}"],
      ["骑驴进城","{{太21:1-11}}","{{可11:1-11}}","{{路19:28-40}}","{{约12:12-19}}"],["最后晚餐","{{太26:26-29}}","{{可14:22-25}}","{{路22:14-20}}","（洗脚{{约13:1-17}}）"],["客西马尼","{{太26:36-46}}","{{可14:32-42}}","{{路22:39-46}}","（{{约18:1}}）"],
      ["钉十字架","{{太27:32-56}}","{{可15:21-41}}","{{路23:26-49}}","{{约19:17-37}}"],["复活","{{太28:1-10}}","{{可16:1-8}}","{{路24:1-12}}","{{约20:1-18}}"],["差遣 / 升天","{{太28:16-20}}","—","{{路24:44-53}}","{{约20:21-23}}"]]))
    b.append('<h2 id="s3">三、受难周：逐日看</h2><div class="pweek">'+"".join(f'<div class="pd2 glass reveal" style="--i:{i}"><span class="pic">{ic}</span><b>{d}</b><p>{md(t)}</p><small>{esc(r)}</small></div>' for i,(d,ic,t,r) in enumerate(PW))+'</div>')
    b.append('<p class="note">'+md("“星期三”的事件是推定；约翰福音以“逾越节前六日”（{{约12:1}}）开始倒数。受难日依多数学者为星期五。")+'</p>')
    b.append('<h3 id="s3b">✝️ 十架七言（传统次序）</h3><div class="words">'+"".join(f'<div class="wd glass reveal" style="--i:{i}"><span class="wn">{i+1}</span><b>{esc(t)}</b><small>{r} · {k}</small></div>' for i,(t,r,k) in enumerate(WORDS))+'</div>')
    b.append('<p class="note">'+md("记忆口诀：**赦 · 救 · 托 · 弃 · 渴 · 成 · 交**。前三句为人代求，中间“离弃”是最深的黑暗（担当罪的咒诅），最后三句是完成与交托。")+'</p>')
    b.append(cq(("hc",44)))
    b.append('<h2 id="s4">四、复活显现</h2>'+tbl(["向谁显现","地点","经文"],APPEAR))
    b.append('<div class="callout"><b>🌅 复活的历史证据：</b>'+md("①空坟（连敌对者也承认，{{太28:11-15}}）；②多次、多人、多地的显现（{{林前15:5-8}}）；③门徒从惧怕到放胆、甘心殉道；④妇女作第一见证人——在当时女子的证词不被重视，编造者不会这样写。")+'</div>'+cq(("hc",45)))
    return "".join(b)
